      "keystrokes": "cat > wolfram_query.py << 'EOF'
#!/usr/bin/env python3
"""Wolfram|Alpha Query Script"""
import os
import sys
import requests

def wolfram_query(query):
    """Query Wolfram|Alpha API and return result."""
    app_id = os.environ.get('WOLFRAM_APP_ID', '')

    if app_id:
        try:
            url = "https://api.wolframalpha.com/v1/result"
            params = {'appid': app_id, 'i': query}
            response = requests.get(url, params=params, timeout=30)
            response.raise_for_status()
            return response.text
        except Exception as e:
            print(f"Wolfram API error: {e}", file=sys.stderr)

    # Fallback to sympy
    try:
        import sympy
        x = sympy.Symbol('x')

        # Parse the query for definite integral
        if 'integrate' in query.lower():
            query_lower = query.lower()
            if 'from' in query_lower and 'to' in query_lower:
                from_idx = query_lower.find('from')
                to_idx = query_lower.find('to')
                expr_str = query[:from_idx].strip()
                bounds = query[from_idx:to_idx].strip()
                upper = query[to_idx:].strip()

                # Extract bounds
                import re
                lower_match = re.search(r'x\s*=\s*(\d+)', bounds)
                upper_match = re.search(r'x\s*=\s*(\d+)', upper)

                if lower_match and upper_match:
                    lower = float(lower_match.group(1))
                    upper = float(upper_match.group(1))
                    expr = sympy.sympify(expr_str.replace('^', '**').replace('x', 'x'))
                    result = sympy.integrate(expr, (x, lower, upper))
                    return str(result)

        return "Could not parse query"
    except Exception as e:
        return f"Sympy error: {e}"

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 wolfram_query.py \"your query\"")
        sys.exit(1)

    query = ' '.join(sys.argv[1:])
    result = wolfram_query(query)
    print(result)
EOF\n",
